            ['start_time' => 1550.88, 'end_time' => 1559.819, 'target_text' => 'The theme of our road trip with Abdullah aid around the whole of the UK this time is hope for the um because we are living', 'source_text' => 'Tema jelajah kami bersama Abdullah Aid di seluruh United Kingdom kali ini adalah \'Harapan Buat Ummah\' kerana kita sedang hidup', 'order' => 434],
            ['start_time' => 1559.919, 'end_time' => 1563.26, 'target_text' => 'In a hopeless world where there is disaster in Gaza.', 'source_text' => 'Dalam dunia yang seakan hilang harapan tatkala bencana menimpa di Gaza.', 'order' => 435],
            ['start_time' => 1563.36, 'end_time' => 1564.86, 'target_text' => 'The genocide continues.', 'source_text' => 'Pembunuhan beramai-ramai masih berterusan.', 'order' => 436],
            ['start_time' => 1564.96, 'end_time' => 1573.1, 'target_text' => 'The perpetration of the most heinous crimes recorded in human history against our brothers and sisters continues and we as', 'source_text' => 'Pelaksanaan jenayah paling kejam yang pernah direkodkan dalam sejarah manusia terhadap saudara kita terus berlaku dan kita sebagai', 'order' => 437],
            ['start_time' => 1573.2, 'end_time' => 1576.14, 'target_text' => 'An Ummah have not been able to do anything about it.', 'source_text' => 'Satu ummah seakan tidak mampu berbuat apa-apa mengenainya.', 'order' => 438],
            ['start_time' => 1576.24, 'end_time' => 1577.98, 'target_text' => 'May Allah forgive us.', 'source_text' => 'Semoga Allah mengampuni kelemahan kita.', 'order' => 439],
