            ['start_time' => 1582.0, 'end_time' => 1584.059, 'target_text' => 'The list is actually endless.', 'source_text' => 'Senarai penderitaannya tiada penghujung.', 'order' => 441],
            ['start_time' => 1584.159, 'end_time' => 1591.579, 'target_text' => 'So much so that in our lives, each one of us, we have issues and problems and difficulties and hardship that no one knows', 'source_text' => 'Sehinggakan dalam kehidupan peribadi kita masing-masing, kita ada masalah, kesulitan, kesempitan dan kepayahan yang tiada siapa tahu', 'order' => 442],
            ['start_time' => 1591.679, 'end_time' => 1592.54, 'target_text' => 'About.', 'source_text' => 'Tentangnya.', 'order' => 443],
            ['start_time' => 1592.64, 'end_time' => 1593.9, 'target_text' => 'Some are trying to get jobs.', 'source_text' => 'Ada yang sedang berusaha mencari rezeki dan pekerjaan.', 'order' => 444],
            ['start_time' => 1594.0, 'end_time' => 1595.26, 'target_text' => 'Some are trying to get married.', 'source_text' => 'Ada yang sedang berikhtiar mencari jodoh.', 'order' => 445],
            ['start_time' => 1595.36, 'end_time' => 1597.02, 'target_text' => 'Some are suffering because of a loss.', 'source_text' => 'Ada yang merana akibat kehilangan orang tersayang.', 'order' => 446],
            ['start_time' => 1597.12, 'end_time' => 1598.62, 'target_text' => 'Some are struggling with their health.', 'source_text' => 'Ada yang sedang bergelut dengan masalah kesihatan.', 'order' => 447],
            ['start_time' => 1598.72, 'end_time' => 1602.059, 'target_text' => 'Some are struggling with their children or because they don\'t have children.', 'source_text' => 'Ada yang diuji dengan anak-anak atau diuji kerana belum dikurniakan zuriat.', 'order' => 448],
            ['start_time' => 1602.159, 'end_time' => 1602.939, 'target_text' => 'So many issues.', 'source_text' => 'Begitu banyak ujian hidup.', 'order' => 449],
            ['start_time' => 1603.039, 'end_time' => 1605.579, 'target_text' => 'We all have a lot of hopelessness.', 'source_text' => 'Kita semua sering diulit rasa putus asa.', 'order' => 450],
            ['start_time' => 1605.679, 'end_time' => 1608.059, 'target_text' => 'We are here to tell you don\'t lose your hope.', 'source_text' => 'Kami hadir di sini untuk menegaskan kepada kalian: Jangan berputus asa!', 'order' => 451],
            ['start_time' => 1608.159, 'end_time' => 1609.179, 'target_text' => 'Allah is your lord.', 'source_text' => 'Allah adalah Tuhanmu.', 'order' => 452],
            ['start_time' => 1609.279, 'end_time' => 1610.3, 'target_text' => 'He knows what he\'s doing.', 'source_text' => 'Dia Maha Mengetahui apa yang sedang dilakukan-Nya.', 'order' => 453],
            ['start_time' => 1610.4, 'end_time' => 1611.34, 'target_text' => 'Allah is the greatest.', 'source_text' => 'Allah Maha Besar.', 'order' => 454],
            ['start_time' => 1611.44, 'end_time' => 1613.98, 'target_text' => 'Ultimately, if we get', 'source_text' => 'Pada akhirnya, sekiranya kita berjaya meraih syurga,', 'order' => 455],
            ['start_time' => 1614.08, 'end_time' => 1617.32, 'target_text' => 'All of this was worth it.', 'source_text' => 'Maka segala kesakitan di dunia ini amat berbaloi.', 'order' => 456],
            ['start_time' => 1617.44, 'end_time' => 1618.939, 'target_text' => 'All of this was worth it.', 'source_text' => 'Segala ujian ini sangat berbaloi.', 'order' => 457],
            ['start_time' => 1619.039, 'end_time' => 1619.66, 'target_text' => 'It\'s okay.', 'source_text' => 'Tidak mengapa.', 'order' => 458],
            ['start_time' => 1619.76, 'end_time' => 1622.28, 'target_text' => 'You\'re going through struggles.', 'source_text' => 'Kalian sedang menempuh keperitan.', 'order' => 459],
