            ['start_time' => 1630.159, 'end_time' => 1636.059, 'target_text' => 'Allah says those who bore patience, our reward for them will be unlimited.', 'source_text' => 'Allah berfirman bahawa mereka yang bersabar, ganjaran pahala bagi mereka adalah tanpa batasan hisab.', 'order' => 461],
            ['start_time' => 1636.159, 'end_time' => 1642.14, 'target_text' => 'When they see the reward for it, they will be saying to Allah, why didn\'t you keep us in that difficulty for longer?', 'source_text' => 'Apabila mereka melihat ganjaran kesabaran tersebut, mereka akan berkata kepada Allah: Mengapakah Engkau tidak membiarkan kami dalam kesukaran itu lebih lama?', 'order' => 462],
            ['start_time' => 1642.24, 'end_time' => 1645.32, 'target_text' => 'We we\'d have had a higher status.', 'source_text' => 'Pasti darjat kami di syurga jauh lebih tinggi.', 'order' => 463],
            ['start_time' => 1645.679, 'end_time' => 1648.62, 'target_text' => 'I\'m not saying turn a blind eye to issues and say, nah, it\'s okay.', 'source_text' => 'Saya tidak menyuruh kalian membutakan mata terhadap masalah lalu berkata: Tidak mengapa,', 'order' => 464],
            ['start_time' => 1648.72, 'end_time' => 1649.98, 'target_text' => 'He stole my million pounds.', 'source_text' => 'Dia mencuri wang satu juta paun saya, biarkanlah,', 'order' => 465],
            ['start_time' => 1650.08, 'end_time' => 1650.48, 'target_text' => 'It\'s okay.', 'source_text' => 'Tidak mengapa,', 'order' => 466],
