            ['start_time' => 1653.919, 'end_time' => 1654.699, 'target_text' => 'Get them.', 'source_text' => 'Dapatkan hak kamu.', 'order' => 469],
            ['start_time' => 1654.799, 'end_time' => 1655.819, 'target_text' => 'Get them back.', 'source_text' => 'Ambil kembali wang tersebut.', 'order' => 470],
            ['start_time' => 1655.919, 'end_time' => 1662.28, 'target_text' => 'I might help you to retrieve them and I won\'t really ask you for the 10%.', 'source_text' => 'Saya mungkin boleh bantu kalian dapatkannya semula dan saya tidak akan meminta komisen 10 peratus.', 'order' => 471],
            ['start_time' => 1662.64, 'end_time' => 1667.26, 'target_text' => 'But to be honest with you, you stand up for your rights in a respectable, honorable way.', 'source_text' => 'Tetapi sejujurnya, pertahankanlah hak kalian dengan cara yang beradab dan terhormat.', 'order' => 472],
            ['start_time' => 1667.36, 'end_time' => 1672.459, 'target_text' => 'You stand up for justice and for what is correct in a respectable and honorable way.', 'source_text' => 'Tegakkanlah keadilan dan kebenaran dengan cara yang bermaruah dan terpuji.', 'order' => 473],
            ['start_time' => 1672.559, 'end_time' => 1674.14, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 474],
