            ['start_time' => 1678.559, 'end_time' => 1683.1, 'target_text' => 'You may go through hardship, difficulty, something calamity you never imagined.', 'source_text' => 'Kamu mungkin terpaksa melalui kesukaran, kepayahan, suatu musibah yang tidak pernah terlintas dalam fikiranmu.', 'order' => 476],
            ['start_time' => 1683.2, 'end_time' => 1686.22, 'target_text' => 'People right now are struggling in Indonesia.', 'source_text' => 'Saudara kita saat ini sedang menderita di Indonesia.', 'order' => 477],
            ['start_time' => 1686.32, 'end_time' => 1689.9, 'target_text' => 'I\'m about to go to Indonesia in the next 3 days.', 'source_text' => 'Saya bakal berlepas ke Indonesia dalam tempoh 3 hari lagi.', 'order' => 478],
            ['start_time' => 1690.0, 'end_time' => 1692.86, 'target_text' => 'Inshallah, we will be in Jakarta and we\'re going to go to Lombok.', 'source_text' => 'Insya-Allah kami akan berada di Jakarta dan kami akan menuju ke Lombok.', 'order' => 479],
            ['start_time' => 1692.96, 'end_time' => 1693.74, 'target_text' => 'Why?', 'source_text' => 'Mengapa?', 'order' => 480],
            ['start_time' => 1693.84, 'end_time' => 1697.26, 'target_text' => 'You know, we\'ve got projects there from a long time with Abdullah aid.', 'source_text' => 'Kalian tahu, kami mempunyai pelbagai projek bantuan di sana sejak sekian lama bersama Abdullah Aid.', 'order' => 481],
            ['start_time' => 1697.36, 'end_time' => 1701.32, 'target_text' => 'On top of that, the worst fires', 'source_text' => 'Di samping itu, kebakaran hutan paling dahsyat', 'order' => 482],
            ['start_time' => 1701.44, 'end_time' => 1706.22, 'target_text' => 'Erupted a few days ago in so many of the islands sweeping through islands.', 'source_text' => 'Tercetus beberapa hari yang lalu di banyak kepulauan lalu membakar merentasi pulau-pulau tersebut.', 'order' => 483],
            ['start_time' => 1706.32, 'end_time' => 1711.02, 'target_text' => 'Who is displaced in the Philippines and in Indonesia and so MANY OTHER COUNTRIES.', 'source_text' => 'Siapakah yang kehilangan tempat tinggal di Filipina, Indonesia, dan banyak negara lain?', 'order' => 484],
            ['start_time' => 1711.12, 'end_time' => 1713.26, 'target_text' => 'OUR BROTHERS AND SISTERS, WHO\'S THERE FOR THEM?', 'source_text' => 'Saudara-saudari kita! Siapakah yang membela nasib mereka di sana?', 'order' => 485],
            ['start_time' => 1713.36, 'end_time' => 1714.939, 'target_text' => 'You are there for them.', 'source_text' => 'Kalianlah yang menghulurkan bantuan kepada mereka.', 'order' => 486],
            ['start_time' => 1715.039, 'end_time' => 1719.42, 'target_text' => 'You have reached out into your pockets and the Muslims are the most generous people on earth.', 'source_text' => 'Kalian telah menyeluk saku memberi sumbangan, dan sesungguhnya umat Islam adalah golongan manusia yang paling pemurah di muka bumi.', 'order' => 487],
            ['start_time' => 1719.52, 'end_time' => 1720.54, 'target_text' => 'You know why?', 'source_text' => 'Tahukah kalian mengapa?', 'order' => 488],
            ['start_time' => 1720.64, 'end_time' => 1725.34, 'target_text' => 'Because we have Nabi Muhammad (sallallahu alaihi wasallam) who taught us to be generous.', 'source_text' => 'Kerana kita mempunyai Nabi Muhammad (sallallahu \'alaihi wasallam) yang mendidik kita supaya sentiasa bersikap dermawan.', 'order' => 489],
            ['start_time' => 1725.44, 'end_time' => 1727.1, 'target_text' => 'A Muslim will always give.', 'source_text' => 'Seorang Muslim akan sentiasa memberi.', 'order' => 490],
            ['start_time' => 1727.2, 'end_time' => 1729.1, 'target_text' => 'A true believer will always give.', 'source_text' => 'Orang beriman yang sejati akan sentiasa memberi.', 'order' => 491],
            ['start_time' => 1729.2, 'end_time' => 1733.66, 'target_text' => 'We are a nation of givers more than we are receivers.', 'source_text' => 'Kita adalah umat yang suka memberi lebih daripada kita menerima.', 'order' => 492],
            ['start_time' => 1733.76, 'end_time' => 1735.26, 'target_text' => 'We are a nation of givers.', 'source_text' => 'Kita adalah umat yang dermawan.', 'order' => 493],
            ['start_time' => 1735.36, 'end_time' => 1740.299, 'target_text' => 'You find a person struggling, he\'ll still take something out and give, but he\'s struggling.', 'source_text' => 'Kamu melihat seseorang yang dalam kesempitan, dia tetap akan mengeluarkan sesuatu lalu memberi walaupun dia sendiri sedang susah.', 'order' => 494],
            ['start_time' => 1740.399, 'end_time' => 1748.059, 'target_text' => 'And the hadith says the best sodaka that you can give is a saddaka when you are fearing poverty yourself and you\'re giving', 'source_text' => 'Dan hadis menyebut bahawa sebaik-baik sedekah yang kamu infakkan adalah sedekah tatkala kamu sendiri takutkan kepapaan dan kamu tetap memberi,', 'order' => 495],
            ['start_time' => 1748.159, 'end_time' => 1749.819, 'target_text' => 'Allah will bless you.', 'source_text' => 'Allah pasti akan memberkati kamu.', 'order' => 496],
            ['start_time' => 1749.919, 'end_time' => 1751.66, 'target_text' => 'I asked about this masid mashallah.', 'source_text' => 'Saya bertanya mengenai masjid ini, masha-Allah.', 'order' => 497],
            ['start_time' => 1751.76, 'end_time' => 1753.42, 'target_text' => 'I want to tell you something amazing.', 'source_text' => 'Saya ingin berkongsi sesuatu yang menakjubkan dengan kalian.', 'order' => 498],
            ['start_time' => 1753.52, 'end_time' => 1758.059, 'target_text' => 'You know, I visit thousands of masids, mashallah, and I pick up an ambiencece in the masid.', 'source_text' => 'Kalian tahu, saya telah mengunjungi ribuan masjid, masha-Allah, dan saya dapat merasakan suasana ketenangan di dalam masjid ini.', 'order' => 499],
            ['start_time' => 1758.159, 'end_time' => 1762.14, 'target_text' => 'I pick up a type of roane because this is the house of Allah.', 'source_text' => 'Saya dapat merasakan sejenis kedamaian rohani kerana tempat ini adalah rumah Allah.', 'order' => 500],
            ['start_time' => 1762.24, 'end_time' => 1767.1, 'target_text' => 'If you are here and you feel connected to this place, it\'s because you\'re connected to Allah.', 'source_text' => 'Sekiranya kalian berada di sini dan merasakan hati kalian terpaut kepada tempat ini, itu kerana kalian terpaut kepada Allah.', 'order' => 501],
            ['start_time' => 1767.2, 'end_time' => 1769.02, 'target_text' => 'So this evening, you\'re all welcome.', 'source_text' => 'Maka pada malam ini, kalian semua sangat dialu-alukan.', 'order' => 502],
            ['start_time' => 1769.12, 'end_time' => 1769.98, 'target_text' => 'More than welcome.', 'source_text' => 'Lebih daripada sekadar dialu-alukan.', 'order' => 503],
            ['start_time' => 1770.08, 'end_time' => 1771.1, 'target_text' => 'You should feel at home.', 'source_text' => 'Kalian sepatutnya berasa selesa seperti di rumah sendiri.', 'order' => 504],
            ['start_time' => 1771.2, 'end_time' => 1772.38, 'target_text' => 'This is home.', 'source_text' => 'Inilah rumah kalian.', 'order' => 505],
            ['start_time' => 1772.48, 'end_time' => 1774.059, 'target_text' => 'Come back again and again and again.', 'source_text' => 'Datanglah kembali berulang kali, lagi dan lagi.', 'order' => 506],
            ['start_time' => 1774.159, 'end_time' => 1775.98, 'target_text' => 'Make sure you\'re here as much as you can.', 'source_text' => 'Pastikan kalian hadir mengimarahkannya sekerap mungkin.', 'order' => 507],
            ['start_time' => 1776.08, 'end_time' => 1779.819, 'target_text' => 'If not this masid, any other masid, inshallah, they are all the houses of Allah.', 'source_text' => 'Jika bukan di masjid ini, di mana-mana masjid lain pun, insya-Allah semuanya adalah rumah Allah.', 'order' => 508],
            ['start_time' => 1779.919, 'end_time' => 1781.9, 'target_text' => 'I heard about Alhajai.', 'source_text' => 'Saya mendengar tentang Al-Haj Okai.', 'order' => 509],
            ['start_time' => 1782.0, 'end_time' => 1783.74, 'target_text' => 'Have you heard that name?', 'source_text' => 'Pernahkah kalian mendengar nama tersebut?', 'order' => 510],
            ['start_time' => 1783.84, 'end_time' => 1785.1, 'target_text' => 'You heard the name.', 'source_text' => 'Kalian pernah mendengar namanya.', 'order' => 511],
            ['start_time' => 1785.2, 'end_time' => 1788.299, 'target_text' => 'May Allah grant him jah and his family.', 'source_text' => 'Semoga Allah mengurniakan syurga kepada beliau dan keluarganya.', 'order' => 512],
            ['start_time' => 1788.399, 'end_time' => 1793.179, 'target_text' => 'I may not have the opportunity to meet him and the others who were with him.', 'source_text' => 'Saya mungkin tidak berpeluang menemui beliau dan mereka yang bersama beliau.', 'order' => 513],
            ['start_time' => 1793.279, 'end_time' => 1793.819, 'target_text' => 'But guess what?', 'source_text' => 'Tetapi tahukah kalian?', 'order' => 514],
            ['start_time' => 1793.919, 'end_time' => 1798.699, 'target_text' => 'It reminds me of the prophet Muhammad (sallallahu alaihi wasallam) when Allah told him to proclaim.', 'source_text' => 'Ia mengingatkan saya kepada Nabi Muhammad (sallallahu \'alaihi wasallam) apabila Allah memerintahkan baginda menyampaikan seruan.', 'order' => 515],
            ['start_time' => 1798.799, 'end_time' => 1799.98, 'target_text' => 'There was no one besides him.', 'source_text' => 'Tiada sesiapa pun bersama baginda ketika itu.', 'order' => 516],
            ['start_time' => 1800.08, 'end_time' => 1803.26, 'target_text' => 'He proclaimed his wife believed Khadijah.', 'source_text' => 'Baginda menyampaikan seruan, isteri baginda Khadijah terus beriman.', 'order' => 517],
            ['start_time' => 1803.36, 'end_time' => 1805.42, 'target_text' => 'His best friend believed Abu Bakr.', 'source_text' => 'Sahabat karib baginda Abu Bakar terus beriman.', 'order' => 518],
            ['start_time' => 1805.52, 'end_time' => 1807.32, 'target_text' => 'His', 'source_text' => 'Ahli', 'order' => 519],
            ['start_time' => 1807.679, 'end_time' => 1815.34, 'target_text' => 'The his closest family member from among those who were his cousins and so on was Ali.', 'source_text' => 'Ahli keluarga terdekat baginda dalam kalangan sepupu baginda ialah Ali.', 'order' => 520],
            ['start_time' => 1815.44, 'end_time' => 1817.26, 'target_text' => 'He believed', 'source_text' => 'Beliau beriman,', 'order' => 521],
            ['start_time' => 1817.36, 'end_time' => 1823.34, 'target_text' => 'Was one of the first who believed and he was in the household of the Prophet ((sallallahu alaihi wasallam)) as a young boy and', 'source_text' => 'Ali merupakan antara insan terawal yang beriman dan beliau diasuh dalam rumah tangga Nabi (sallallahu \'alaihi wasallam) sejak kanak-kanak,', 'order' => 522],
            ['start_time' => 1823.44, 'end_time' => 1831.9, 'target_text' => 'You know what immediately he\'s he said his shahada they knew so these people believed and what happened it started off with', 'source_text' => 'Dan tahukah kalian serta-merta beliau melafazkan dua kalimah syahadah. Mereka beriman, dan apakah yang berlaku? Ia bermula', 'order' => 523],
            ['start_time' => 1832.0, 'end_time' => 1839.1, 'target_text' => 'Just a few they were persecuted it grew today there are massagid and followers billions and billions across the globe over', 'source_text' => 'Hanya dengan beberapa individu, mereka ditindas, kemudian dakwah berkembang dan hari ini terdapat masjid-masjid dan berbilion pengikut di seluruh dunia merentasi', 'order' => 524],
            ['start_time' => 1839.2, 'end_time' => 1847.8, 'target_text' => 'Time and generations you saw the seed Allah will give it acceptance I\'m sure alaj Okai and the others', 'source_text' => 'Masa dan generasi. Kamu semaikan benih kebaikan, Allah pasti akan mengurniakan penerimaan. Saya yakin Al-Haj Okai dan para pengasas terdahulu', 'order' => 525],
            ['start_time' => 1848.08, 'end_time' => 1854.62, 'target_text' => 'They would not have known what is going to happen here but they started off the seed was sown I\'m sure there are some others', 'source_text' => 'Tidak mengetahui apa yang bakal terjadi pada hari ini, namun mereka memulakannya, benih telah disemai. Saya yakin ada sebahagian lain', 'order' => 526],
            ['start_time' => 1854.72, 'end_time' => 1861.819, 'target_text' => 'From amongst you you swed some seeds you did some good mashallah Allah will allow it to grow just do something and even when', 'source_text' => 'Dalam kalangan kalian yang telah menyemai benih kebaikan, melakukan amal soleh, masha-Allah Allah akan menyuburkannya, lakukanlah sesuatu dan apabila', 'order' => 527],
            ['start_time' => 1861.919, 'end_time' => 1864.78, 'target_text' => 'You depart it becomes aar', 'source_text' => 'Kamu telah meninggal dunia, ia akan menjadi amal jariah yang berterusan pahalanya.', 'order' => 528],
            ['start_time' => 1864.88, 'end_time' => 1870.86, 'target_text' => 'I look at a lot of Islamic communities I like to ask them where did this start when did it start who started it what happened', 'source_text' => 'Bila saya melihat banyak komuniti Islam, saya gemar bertanya kepada mereka: Di manakah ia bermula, bilakah ia bermula, siapakah pengasasnya dan apa kisahnya?', 'order' => 529],
            ['start_time' => 1870.96, 'end_time' => 1875.1, 'target_text' => 'Why I want to be inspired that when someone swed a small tiny seat.', 'source_text' => 'Mengapa? Kerana saya ingin mengambil inspirasi bagaimana seseorang menyemai benih kecil yang mulus.', 'order' => 530],
            ['start_time' => 1875.2, 'end_time' => 1876.54, 'target_text' => 'You know what they usually say?', 'source_text' => 'Tahukah kalian apa yang biasanya mereka ceritakan?', 'order' => 531],
            ['start_time' => 1876.64, 'end_time' => 1883.34, 'target_text' => 'Oh, you know, this community started in one room that was in somebody\'s business in the corner and they just started it as', 'source_text' => 'Mereka berkata, komuniti ini dahulunya bermula hanya dalam sebuah bilik kecil di sudut kedai perniagaan seseorang dan mereka mulakan sekadar', 'order' => 532],
            ['start_time' => 1883.44, 'end_time' => 1885.5, 'target_text' => 'A salah facility and later it grew.', 'source_text' => 'Sebagai ruang solat, dan lama-kelamaan ia berkembang mekar.', 'order' => 533],
            ['start_time' => 1885.6, 'end_time' => 1886.459, 'target_text' => 'It grew into what?', 'source_text' => 'Berkembang menjadi apa?', 'order' => 534],
            ['start_time' => 1886.559, 'end_time' => 1890.54, 'target_text' => 'It grew into the national mosque of the country.', 'source_text' => 'Berkembang menjadi masjid kebangsaan negara tersebut!', 'order' => 535],
            ['start_time' => 1890.64, 'end_time' => 1892.38, 'target_text' => 'How did Allah let that happen?', 'source_text' => 'Bagaimanakah Allah mentakdirkan perkara itu berlaku?', 'order' => 536],
            ['start_time' => 1892.48, 'end_time' => 1893.98, 'target_text' => 'Because Allah says, "This is my house.', 'source_text' => 'Kerana Allah berfirman: Ini adalah rumah-Ku.', 'order' => 537],
            ['start_time' => 1894.08, 'end_time' => 1897.26, 'target_text' => 'Do you reckon I\'m just going to leave it like this?" It has to grow, man.', 'source_text' => 'Adakah kamu menyangka Aku akan membiarkannya terbengkalai begitu sahaja? Ia pasti akan berkembang luas!', 'order' => 538],
            ['start_time' => 1897.36, 'end_time' => 1904.54, 'target_text' => 'If you were sincere and you really want to serve the Ummah and not just your tiny group of people, Allah will let it grow.', 'source_text' => 'Sekiranya kalian ikhlas dan benar-benar ingin berkhidmat untuk ummah dan bukan sekadar kelompok kecil kalian, Allah akan menyuburkannya.', 'order' => 539],
            ['start_time' => 1904.64, 'end_time' => 1907.5, 'target_text' => 'Today in this masid, we have people from all walks of life.', 'source_text' => 'Hari ini di dalam masjid ini, kita memiliki jemaah dari pelbagai latar belakang kehidupan.', 'order' => 540],
            ['start_time' => 1907.6, 'end_time' => 1916.14, 'target_text' => 'I see ethnicities in in the in front of in front of me right now that proves that the Ummah is alive.', 'source_text' => 'Saya melihat pelbagai bangsa dan etnik di hadapan saya saat ini yang membuktikan bahawa ummah ini subur dan bernyawa.', 'order' => 541],
            ['start_time' => 1916.24, 'end_time' => 1919.74, 'target_text' => 'Let\'s treat each other with respect and honor no matter where we come from.', 'source_text' => 'Marilah kita saling melayani dengan penuh rasa hormat dan kemuliaan tidak kira dari mana asal usul kita.', 'order' => 542],
            ['start_time' => 1919.84, 'end_time' => 1921.66, 'target_text' => 'Let\'s treat each other with dignity.', 'source_text' => 'Marilah kita memperlakukan satu sama lain dengan maruah dan adab yang tinggi.', 'order' => 543],
            ['start_time' => 1921.76, 'end_time' => 1923.02, 'target_text' => 'That\'s what Islam is.', 'source_text' => 'Itulah hakikat ajaran Islam yang suci.', 'order' => 544],
            ['start_time' => 1923.12, 'end_time' => 1924.939, 'target_text' => 'No matter where we come from.', 'source_text' => 'Tidak kira dari pelosok mana pun kita datang.', 'order' => 545],
            ['start_time' => 1925.039, 'end_time' => 1933.66, 'target_text' => 'In fact, so much so that the non-Muslims out there need to know and feel that we are also human beings who care for entire', 'source_text' => 'Malah sehingga ke tahap orang bukan Islam di luar sana perlu menyedari dan merasakan bahawa kita adalah insan yang prihatin terhadap seluruh', 'order' => 546],
            ['start_time' => 1933.76, 'end_time' => 1935.56, 'target_text' => 'Humanity.', 'source_text' => 'Umat manusia.', 'order' => 547],
            ['start_time' => 1935.679, 'end_time' => 1938.059, 'target_text' => 'May Allah Almighty help us.', 'source_text' => 'Semoga Allah Yang Maha Kuasa membantu kita.', 'order' => 548],
            ['start_time' => 1938.159, 'end_time' => 1938.939, 'target_text' => 'This is the dean.', 'source_text' => 'Inilah agama kita.', 'order' => 549],
            ['start_time' => 1939.039, 'end_time' => 1940.14, 'target_text' => 'This is what Allah brought.', 'source_text' => 'Inilah ajaran yang dibawa oleh Allah.', 'order' => 550],
            ['start_time' => 1940.24, 'end_time' => 1943.1, 'target_text' => 'This is what Nabi Muhammad (sallallahu alaihi wasallam) taught.', 'source_text' => 'Inilah yang diajarkan oleh Nabi Muhammad (sallallahu \'alaihi wasallam).', 'order' => 551],
            ['start_time' => 1943.2, 'end_time' => 1944.62, 'target_text' => 'Now he recognizes you.', 'source_text' => 'Kini baginda mengenali kalian.', 'order' => 552],
            ['start_time' => 1944.72, 'end_time' => 1945.819, 'target_text' => 'Guess what?', 'source_text' => 'Tahukah kalian apa kesannya?', 'order' => 553],
            ['start_time' => 1945.919, 'end_time' => 1947.579, 'target_text' => 'He will be proud of you.', 'source_text' => 'Baginda pasti akan berbangga dengan kalian.', 'order' => 554],
            ['start_time' => 1947.679, 'end_time' => 1948.079, 'target_text' => 'Wow.', 'source_text' => 'Hebat sekali.', 'order' => 555],
            ['start_time' => 1948.08, 'end_time' => 1949.1, 'target_text' => 'What did you do on earth?', 'source_text' => 'Apakah amalan yang telah kamu lakukan di dunia?', 'order' => 556],
            ['start_time' => 1949.2, 'end_time' => 1951.34, 'target_text' => 'You did a lot.', 'source_text' => 'Kamu telah melakukan banyak kebajikan.', 'order' => 557],
            ['start_time' => 1951.44, 'end_time' => 1951.98, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 558],
            ['start_time' => 1952.08, 'end_time' => 1953.26, 'target_text' => 'I want you to come and sit here.', 'source_text' => 'Saya mahu kamu ke mari dan duduk di sini.', 'order' => 559],
            ['start_time' => 1953.36, 'end_time' => 1955.5, 'target_text' => 'And I want you to come and sit here with me inshallah.', 'source_text' => 'Dan saya mahu kamu datang duduk di sini bersama saya, insya-Allah.', 'order' => 560],
            ['start_time' => 1955.6, 'end_time' => 1957.9, 'target_text' => 'Stand up and come sit here.', 'source_text' => 'Bangun dan marilah duduk di sini.', 'order' => 561],
            ['start_time' => 1958.0, 'end_time' => 1958.459, 'target_text' => 'That\'s it.', 'source_text' => 'Begitulah.', 'order' => 562],
            ['start_time' => 1958.559, 'end_time' => 1960.059, 'target_text' => 'What\'s your name?', 'source_text' => 'Siapakah namamu?', 'order' => 563],
            ['start_time' => 1960.159, 'end_time' => 1962.22, 'target_text' => 'And what\'s your name?', 'source_text' => 'Dan siapakah nama kamu?', 'order' => 564],
            ['start_time' => 1962.32, 'end_time' => 1962.78, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 565],
            ['start_time' => 1962.88, 'end_time' => 1963.28, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 566],
            ['start_time' => 1963.36, 'end_time' => 1963.819, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 567],
            ['start_time' => 1963.919, 'end_time' => 1966.299, 'target_text' => 'Lovely to see you guys and to see all these youth.', 'source_text' => 'Gembira sungguh melihat kalian berdua dan melihat para pemuda belia ini.', 'order' => 568],
            ['start_time' => 1966.399, 'end_time' => 1967.98, 'target_text' => 'Look at these uh youngsters here.', 'source_text' => 'Lihatlah anak-anak muda di sini.', 'order' => 569],
            ['start_time' => 1968.08, 'end_time' => 1968.54, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 570],
            ['start_time' => 1968.64, 'end_time' => 1969.98, 'target_text' => 'Amazing.', 'source_text' => 'Sungguh menakjubkan.', 'order' => 571],
            ['start_time' => 1970.08, 'end_time' => 1972.22, 'target_text' => 'So this is Islam.', 'source_text' => 'Maka inilah keindahan Islam.', 'order' => 572],
            ['start_time' => 1972.32, 'end_time' => 1976.54, 'target_text' => 'And this is why we say my beloved brothers and sisters, don\'t let someone take it away from you.', 'source_text' => 'Dan sebab itulah kami berpesan, wahai saudara dan saudariku yang dikasihi, jangan biarkan sesiapa pun merampas nikmat iman ini daripada kalian.', 'order' => 573],
            ['start_time' => 1976.64, 'end_time' => 1979.26, 'target_text' => 'Do you know what they\'re doing right now?', 'source_text' => 'Tahukah kalian apa yang sedang musuh lakukan sekarang?', 'order' => 574],
            ['start_time' => 1979.36, 'end_time' => 1982.78, 'target_text' => 'They are reading the verses of the Quran without context.', 'source_text' => 'Mereka membaca ayat-ayat Al-Quran di luar konteks yang sebenar.', 'order' => 575],
            ['start_time' => 1982.88, 'end_time' => 1989.98, 'target_text' => 'So they pick up verses and there are verses of the Bible that are far worse and dangerous if taken without context.', 'source_text' => 'Mereka mencabut beberapa ayat, sedangkan ada ayat-ayat Bible yang jauh lebih keras dan merbahaya sekiranya diambil tanpa konteks.', 'order' => 576],
            ['start_time' => 1990.08, 'end_time' => 1997.819, 'target_text' => 'But they won\'t do that because we as Muslims, we don\'t go around spying on others and searching in their in their revelations', 'source_text' => 'Tetapi orang Islam tidak akan melakukan perkara itu kerana kita tidak sesekali mengintip orang lain atau menyelongkar kitab suci mereka', 'order' => 577],
            ['start_time' => 1997.919, 'end_time' => 1999.74, 'target_text' => 'To try and look for fault in them.', 'source_text' => 'Semata-mata untuk mencari kesalahan mereka.', 'order' => 578],
            ['start_time' => 1999.84, 'end_time' => 2001.819, 'target_text' => 'We are so content with what we have.', 'source_text' => 'Kita berasa amat tenang dan cukup dengan apa yang kita miliki.', 'order' => 579],
            ['start_time' => 2001.919, 'end_time' => 2003.419, 'target_text' => 'We don\'t have the time to do that.', 'source_text' => 'Kita tidak ada masa terluang untuk berbuat sedemikian.', 'order' => 580],
            ['start_time' => 2003.519, 'end_time' => 2011.66, 'target_text' => 'But they are so discontent with what they have that they come and intentionally create and misconstrue verses of the Quran', 'source_text' => 'Tetapi mereka berasa begitu gelisah dan tidak puas hati dengan apa yang mereka ada sehingga sengaja memutarbelitkan ayat-ayat Al-Quran', 'order' => 581],
            ['start_time' => 2011.76, 'end_time' => 2018.78, 'target_text' => 'Taken totally without context or out of context and they will tell you Islam is preaching extremism.', 'source_text' => 'Yang diambil terputus daripada konteksnya lalu mendakwa kononnya Islam menyebarkan ekstremisme.', 'order' => 582],
            ['start_time' => 2018.88, 'end_time' => 2027.02, 'target_text' => 'So now it becomes prohibited to read certain verses of the Quran because they took them out of context and then they want', 'source_text' => 'Maka kini timbul larangan membaca ayat-ayat Al-Quran tertentu kerana mereka mencabutnya daripada konteks lalu mereka mahu', 'order' => 583],
            ['start_time' => 2027.12, 'end_time' => 2030.54, 'target_text' => 'To make it law in the land to say you\'re not allowed to read this.', 'source_text' => 'Menjadikannya sebagai undang-undang di negara ini kononnya dilarang membaca ayat sekian.', 'order' => 584],
            ['start_time' => 2030.64, 'end_time' => 2034.059, 'target_text' => 'Imm was jailed because he was reading this verse of the Quran in prayer.', 'source_text' => 'Imam dipenjarakan semata-mata kerana membaca ayat Al-Quran ini di dalam solatnya!', 'order' => 585],
            ['start_time' => 2034.159, 'end_time' => 2035.579, 'target_text' => 'How can we do this?', 'source_text' => 'Bagaimanakah perkara sebegini boleh dibiarkan berlaku?', 'order' => 586],
            ['start_time' => 2035.679, 'end_time' => 2037.419, 'target_text' => 'But this is what\'s going on.', 'source_text' => 'Tetapi itulah hakikat yang sedang berlangsung.', 'order' => 587],
            ['start_time' => 2037.519, 'end_time' => 2038.62, 'target_text' => 'Let\'s be alert.', 'source_text' => 'Marilah kita sentiasa berwaspada.', 'order' => 588],
            ['start_time' => 2038.72, 'end_time' => 2039.819, 'target_text' => 'Always talk to people.', 'source_text' => 'Sentiasalah berdialog dan berbicara dengan orang ramai.', 'order' => 589],
            ['start_time' => 2039.919, 'end_time' => 2041.26, 'target_text' => 'Listen, take things in context.', 'source_text' => 'Dengarlah, fahamilah sesuatu perkara mengikut konteksnya yang sebenar.', 'order' => 590],
            ['start_time' => 2041.36, 'end_time' => 2042.54, 'target_text' => 'I might not understand.', 'source_text' => 'Mungkin saya tidak faham sepenuhnya.', 'order' => 591],
            ['start_time' => 2042.64, 'end_time' => 2043.579, 'target_text' => 'They\'ll grab you.', 'source_text' => 'Mereka akan menarik kamu secara mengejut.', 'order' => 592],
            ['start_time' => 2043.679, 'end_time' => 2045.9, 'target_text' => 'They\'ll say, "Dawood, come here." So Dawood stands up.', 'source_text' => 'Mereka berkata: Dawood, mari ke sini! Lalu Dawood pun berdiri.', 'order' => 593],
            ['start_time' => 2046.0, 'end_time' => 2046.86, 'target_text' => 'He\'s Are you a Muslim?', 'source_text' => 'Mereka bertanya: Adakah kamu seorang Muslim?', 'order' => 594],
            ['start_time' => 2046.96, 'end_time' => 2047.278, 'target_text' => 'Yes.', 'source_text' => 'Ya.', 'order' => 595],
            ['start_time' => 2047.279, 'end_time' => 2047.979, 'target_text' => 'Are you a half?', 'source_text' => 'Adakah kamu menghafal Al-Quran?', 'order' => 596],
            ['start_time' => 2048.079, 'end_time' => 2050.14, 'target_text' => 'Yes, I\'ve memorized six portions of the Quran.', 'source_text' => 'Ya, saya sudah menghafal enam juzuk Al-Quran.', 'order' => 597],
            ['start_time' => 2050.24, 'end_time' => 2052.299, 'target_text' => 'Have you memorized a little bit of the Quran?', 'source_text' => 'Adakah kamu menghafal sebahagian Al-Quran?', 'order' => 598],
            ['start_time' => 2052.399, 'end_time' => 2053.66, 'target_text' => 'Who is Daw?', 'source_text' => 'Siapakah Dawood di sini?', 'order' => 599],
            ['start_time' => 2053.76, 'end_time' => 2054.16, 'target_text' => 'You are.', 'source_text' => 'Kamulah orangnya.', 'order' => 600],
            ['start_time' => 2054.24, 'end_time' => 2055.819, 'target_text' => 'Did you memorize some Quran?', 'source_text' => 'Adakah kamu menghafal sedikit Al-Quran?', 'order' => 601],
            ['start_time' => 2055.919, 'end_time' => 2056.779, 'target_text' => 'Okay, you did.', 'source_text' => 'Ya, kamu menghafalnya.', 'order' => 602],
            ['start_time' => 2056.879, 'end_time' => 2062.539, 'target_text' => 'So, if someone just gets this youngster up and says he\'s memorized some Quran, right, tell us what does this mean?', 'source_text' => 'Maka jika seseorang sengaja memanggil anak muda ini lalu berkata dia hafal Al-Quran, beritahu kami apa maksud ayat ini?', 'order' => 603],
            ['start_time' => 2062.639, 'end_time' => 2064.299, 'target_text' => 'Is he the right person to talk to?', 'source_text' => 'Adakah anak muda itu rujukan yang tepat untuk diajukan soalan tafsir yang mendalam?', 'order' => 604],
            ['start_time' => 2064.399, 'end_time' => 2064.86, 'target_text' => 'Not at all.', 'source_text' => 'Sama sekali tidak!', 'order' => 605],
            ['start_time' => 2064.96, 'end_time' => 2065.739, 'target_text' => 'But that\'s what they do.', 'source_text' => 'Tetapi itulah taktik yang mereka lakukan.', 'order' => 606],
            ['start_time' => 2065.839, 'end_time' => 2071.499, 'target_text' => 'They\'ll come with huge cameras and they\'ll make they\'ll ask someone who doesn\'t know the answer and that person says, "Oh,', 'source_text' => 'Mereka akan membawa kamera besar dan sengaja menyoal individu yang tidak tahu jawapannya, lalu orang itu menjawab: Wah,', 'order' => 607],
            ['start_time' => 2071.599, 'end_time' => 2073.979, 'target_text' => 'I really don\'t know." Then watch the comment section.', 'source_text' => 'Saya benar-benar tidak tahu. Kemudian saksikanlah apa yang berlaku di ruangan komen.', 'order' => 608],
            ['start_time' => 2074.079, 'end_time' => 2078.7, 'target_text' => 'The bots will create and generate public opinion like crazy against who?', 'source_text' => 'Akaun-akaun bot akan membina dan mencetuskan persepsi umum yang ganas membenci siapa?', 'order' => 609],
            ['start_time' => 2078.8, 'end_time' => 2080.38, 'target_text' => 'Against you and I innocent people.', 'source_text' => 'Membenci diri kalian dan saya, insan-insan yang tidak bersalah!', 'order' => 610],
            ['start_time' => 2080.48, 'end_time' => 2084.299, 'target_text' => 'If they did that to the Jewish people, we would be dead.', 'source_text' => 'Sekiranya mereka melakukan tohmahan itu terhadap orang Yahudi, kita sudah pasti dicop teruk.', 'order' => 611],
            ['start_time' => 2084.399, 'end_time' => 2086.14, 'target_text' => 'But when they do it to us, it\'s permissible.', 'source_text' => 'Tetapi apabila mereka melakukannya terhadap umat Islam, ia dianggap dibolehkan.', 'order' => 612],
            ['start_time' => 2086.24, 'end_time' => 2086.64, 'target_text' => 'It\'s okay.', 'source_text' => 'Ia dianggap tidak mengapa.', 'order' => 613],
            ['start_time' => 2086.72, 'end_time' => 2087.979, 'target_text' => 'Do it to anyone and everyone.', 'source_text' => 'Lakukanlah sesuka hati kepada sesiapa sahaja.', 'order' => 614],
            ['start_time' => 2088.079, 'end_time' => 2091.259, 'target_text' => 'Keep on just just keep on hitting the Muslims so badly.', 'source_text' => 'Teruskanlah menyerang dan memburuk-burukkan orang Islam sewenang-wenangnya.', 'order' => 615],
            ['start_time' => 2091.359, 'end_time' => 2093.34, 'target_text' => 'They would have called it anti-semitism.', 'source_text' => 'Jika kena kepada orang lain, mereka terus menuduhnya sebagai anti-Semitisme.', 'order' => 616],
            ['start_time' => 2093.44, 'end_time' => 2095.019, 'target_text' => 'Do you know the meaning of semitism?', 'source_text' => 'Tahukah kalian maksud sebenar perkataan Semitik?', 'order' => 617],
            ['start_time' => 2095.119, 'end_time' => 2096.94, 'target_text' => 'It includes Islam and Christianity.', 'source_text' => 'Ia turut merangkumi bangsa dan rumpun agama Islam dan Kristian.', 'order' => 618],
            ['start_time' => 2097.04, 'end_time' => 2099.82, 'target_text' => 'Those are semite religions.', 'source_text' => 'Agama-agama tersebut adalah agama rumpun Semitik.', 'order' => 619],
            ['start_time' => 2099.92, 'end_time' => 2102.44, 'target_text' => 'Did you ever know that', 'source_text' => 'Tahukah kalian hakikat', 'order' => 620],
            ['start_time' => 2102.88, 'end_time' => 2105.58, 'target_text' => 'Christianity and Islam are semite religions?', 'source_text' => 'Bahawa Kristian dan Islam adalah agama-agama rumpun Semitik?', 'order' => 621],
            ['start_time' => 2105.68, 'end_time' => 2106.38, 'target_text' => 'Why?', 'source_text' => 'Mengapa?', 'order' => 622],
            ['start_time' => 2106.48, 'end_time' => 2114.62, 'target_text' => 'Why are you allowed to attack Islam and lie about it and speak about it outside of context and nobody\'s allowed to say anything', 'source_text' => 'Mengapakah kalian dibenarkan menyerang Islam, berdusta mengenainya dan memfitnah di luar konteks, tetapi tiada siapa dibenarkan menegur', 'order' => 623],
            ['start_time' => 2114.72, 'end_time' => 2115.82, 'target_text' => 'About you?', 'source_text' => 'Mengenai kalian?', 'order' => 624],
            ['start_time' => 2115.92, 'end_time' => 2116.54, 'target_text' => 'Why?', 'source_text' => 'Mengapa?', 'order' => 625],
            ['start_time' => 2116.64, 'end_time' => 2118.38, 'target_text' => 'Because you have an agenda.', 'source_text' => 'Kerana kalian mempunyai agenda terselindung.', 'order' => 626],
            ['start_time' => 2118.48, 'end_time' => 2119.499, 'target_text' => 'May Allah protect us.', 'source_text' => 'Semoga Allah melindungi kita semua.', 'order' => 627],
            ['start_time' => 2119.599, 'end_time' => 2120.38, 'target_text' => 'Let\'s be fair.', 'source_text' => 'Marilah kita berlaku adil.', 'order' => 628],
            ['start_time' => 2120.48, 'end_time' => 2123.9, 'target_text' => 'If we want peace on earth, we need to be fair and just.', 'source_text' => 'Sekiranya kita mahukan keamanan di bumi, kita wajib bersikap adil dan saksama.', 'order' => 629],
            ['start_time' => 2124.0, 'end_time' => 2127.259, 'target_text' => 'The minute there is no justice, you\'re not going to get peace.', 'source_text' => 'Sebaik sahaja keadilan ditiadakan, kalian tidak akan sesekali menikmati keamanan.', 'order' => 630],
            ['start_time' => 2127.359, 'end_time' => 2133.019, 'target_text' => 'Even in your own home, if you\'re oppressive and aggressive, your home is going to break into 10 pieces.', 'source_text' => 'Bahkan dalam rumah tangga kalian sendiri, jika kamu zalim dan kasar, rumah tanggamu akan hancur bersepai.', 'order' => 631],
            ['start_time' => 2133.119, 'end_time' => 2134.14, 'target_text' => 'You need to be just.', 'source_text' => 'Kamu wajib berlaku adil.', 'order' => 632],
            ['start_time' => 2134.24, 'end_time' => 2135.739, 'target_text' => 'You need to be fair.', 'source_text' => 'Kamu wajib bersikap saksama.', 'order' => 633],
            ['start_time' => 2135.839, 'end_time' => 2138.38, 'target_text' => 'That is the cornerstone of peace.', 'source_text' => 'Keadilan itulah tiang seri utama bagi keamanan.', 'order' => 634],
            ['start_time' => 2138.48, 'end_time' => 2141.66, 'target_text' => 'Peace comes with justice and justice comes with peace.', 'source_text' => 'Keamanan lahir daripada keadilan, dan keadilan membawa keamanan.', 'order' => 635],
            ['start_time' => 2141.76, 'end_time' => 2143.66, 'target_text' => 'May Allah protect us.', 'source_text' => 'Semoga Allah melindungi kita.', 'order' => 636],
            ['start_time' => 2143.76, 'end_time' => 2146.3, 'target_text' => 'You can see we are all passionate about the same things.', 'source_text' => 'Kalian dapat melihat kita semua bersemangat memperjuangkan perkara yang sama.', 'order' => 637],
            ['start_time' => 2146.4, 'end_time' => 2151.019, 'target_text' => 'And I can tell you that I\'m in a community here in Dundee that is extremely passionate.', 'source_text' => 'Dan saya boleh tegaskan bahawa saya berada dalam komuniti di Dundee ini yang mempunyai semangat juang yang amat membara.', 'order' => 638],
            ['start_time' => 2151.119, 'end_time' => 2155.58, 'target_text' => 'I can see the youth and I can see the energy and there is a lot of energy in the air here today.', 'source_text' => 'Saya dapat melihat golongan belia, saya dapat merasakan energinya, dan terdapat getaran semangat yang luar biasa di sini hari ini.', 'order' => 639],
            ['start_time' => 2155.68, 'end_time' => 2156.7, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 640],
            ['start_time' => 2156.8, 'end_time' => 2163.499, 'target_text' => 'May Allah help us to channel that energy in the right direction so that we can contribute positively to society and community', 'source_text' => 'Semoga Allah membantu kita menyalurkan tenaga tersebut ke arah yang betul agar kita dapat menyumbang secara positif kepada masyarakat dan komuniti,', 'order' => 641],
            ['start_time' => 2163.599, 'end_time' => 2167.399, 'target_text' => 'And we can serve and we can prove them wrong.', 'source_text' => 'Dan kita dapat berbakti serta membuktikan bahawa tuduhan mereka itu salah sama sekali.', 'order' => 642],
            ['start_time' => 2167.599, 'end_time' => 2173.82, 'target_text' => 'But my brothers and sisters, there is a campaign against your dean in order to snatch it away from you.', 'source_text' => 'Namun wahai saudara dan saudariku, wujud kempen jahat terhadap agama kalian untuk merampasnya daripada genggaman kalian.', 'order' => 643],
            ['start_time' => 2173.92, 'end_time' => 2176.94, 'target_text' => 'No matter who you are, you are not a bad person.', 'source_text' => 'Tidak kira siapa pun diri kalian, kalian bukan orang yang jahat.', 'order' => 644],
            ['start_time' => 2177.04, 'end_time' => 2178.22, 'target_text' => 'Keep trying.', 'source_text' => 'Teruskanlah mencuba.', 'order' => 645],
            ['start_time' => 2178.32, 'end_time' => 2179.739, 'target_text' => 'Be proud that you\'re a Muslim.', 'source_text' => 'Banggalah menjadi seorang Muslim.', 'order' => 646],
            ['start_time' => 2179.839, 'end_time' => 2181.42, 'target_text' => 'Hold your identity high.', 'source_text' => 'Julanglah identiti Islam kalian setinggi-tingginya.', 'order' => 647],
            ['start_time' => 2181.52, 'end_time' => 2184.919, 'target_text' => 'I\'m in the I\'m in the um ofahillah.', 'source_text' => 'Daku adalah sebahagian daripada umat Nabi Muhammad Rasulullah.', 'order' => 648],
            ['start_time' => 2185.599, 'end_time' => 2186.54, 'target_text' => 'I might be weak.', 'source_text' => 'Aku mungkin serba lemah.', 'order' => 649],
            ['start_time' => 2186.64, 'end_time' => 2188.3, 'target_text' => 'I might be struggling with my prayer.', 'source_text' => 'Aku mungkin masih bergelut menjaga solatku.', 'order' => 650],
            ['start_time' => 2188.4, 'end_time' => 2189.58, 'target_text' => 'I might be a sinful person.', 'source_text' => 'Aku mungkin insan yang banyak melakukan dosa.', 'order' => 651],
            ['start_time' => 2189.68, 'end_time' => 2190.3, 'target_text' => 'But guess what?', 'source_text' => 'Namun tahukah kalian?', 'order' => 652],
            ['start_time' => 2190.4, 'end_time' => 2193.499, 'target_text' => 'I love my Allah and I love my prophet, (peace be upon him).', 'source_text' => 'Daku amat mencintai Allah dan daku amat mencintai Rasul-Nya (peace be upon him).', 'order' => 653],
            ['start_time' => 2193.599, 'end_time' => 2198.54, 'target_text' => 'And I\'m going to try and I\'m going to keep trying and I\'m going to stand up for them and I\'m going to make sure that I don\'t', 'source_text' => 'Dan daku akan terus mencuba dan berusaha gigih, daku akan membela mereka dan daku akan memastikan bahawa daku tidak', 'order' => 654],
            ['start_time' => 2198.64, 'end_time' => 2199.979, 'target_text' => 'Let them down.', 'source_text' => 'Akan mengecewakan mereka.', 'order' => 655],
            ['start_time' => 2200.079, 'end_time' => 2201.18, 'target_text' => 'That\'s the dean of Allah.', 'source_text' => 'Itulah hakikat agama Allah.', 'order' => 656],
            ['start_time' => 2201.28, 'end_time' => 2202.94, 'target_text' => 'That\'s my message for you today.', 'source_text' => 'Itulah pesanan utama saya untuk kalian pada hari ini.', 'order' => 657],
            ['start_time' => 2203.04, 'end_time' => 2206.46, 'target_text' => 'No matter what your weakness is and who you are, be a proud Muslim.', 'source_text' => 'Tidak kira apa jua kelemahan kalian dan siapa pun kalian, banggalah menjadi seorang Muslim.', 'order' => 658],
            ['start_time' => 2206.56, 'end_time' => 2208.7, 'target_text' => 'That will be your ticket to paradise.', 'source_text' => 'Itulah yang akan menjadi tiket kalian menuju ke syurga.', 'order' => 659],
            ['start_time' => 2208.8, 'end_time' => 2210.94, 'target_text' => 'Don\'t hide your faith and be embarrassed about it.', 'source_text' => 'Jangan sembunyikan pegangan iman kalian dan jangan berasa malu dengannya.', 'order' => 660],
            ['start_time' => 2211.04, 'end_time' => 2211.44, 'target_text' => 'So what?', 'source_text' => 'Jadi apa masalahnya?', 'order' => 661],
            ['start_time' => 2211.52, 'end_time' => 2212.46, 'target_text' => 'What is your name?', 'source_text' => 'Siapakah nama kamu?', 'order' => 662],
            ['start_time' => 2212.56, 'end_time' => 2214.7, 'target_text' => 'My name is Abdullah Aziz.', 'source_text' => 'Nama saya Abdul Aziz.', 'order' => 663],
            ['start_time' => 2214.8, 'end_time' => 2215.2, 'target_text' => 'So what?', 'source_text' => 'Jadi apa masalahnya?', 'order' => 664],
            ['start_time' => 2215.28, 'end_time' => 2216.78, 'target_text' => 'It\'s a beautiful name.', 'source_text' => 'Ia nama yang amat indah.', 'order' => 665],
            ['start_time' => 2216.88, 'end_time' => 2217.9, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 666],
            ['start_time' => 2218.0, 'end_time' => 2221.58, 'target_text' => 'You don\'t need to lie because you see a guy, mashallah, with blonde hair and blue eyes.', 'source_text' => 'Kamu tidak perlu berbohong semata-mata kerana kamu melihat seseorang, masha-Allah, berambut perang dan bermata biru.', 'order' => 667],
            ['start_time' => 2221.68, 'end_time' => 2222.46, 'target_text' => 'What\'s your name?', 'source_text' => 'Siapakah nama kamu?', 'order' => 668],
            ['start_time' => 2222.56, 'end_time' => 2224.36, 'target_text' => 'Zezy.', 'source_text' => 'Zezy.', 'order' => 669],
            ['start_time' => 2225.359, 'end_time' => 2227.34, 'target_text' => 'Not zezy.', 'source_text' => 'Bukan Zezy!', 'order' => 670],
            ['start_time' => 2227.44, 'end_time' => 2227.84, 'target_text' => 'Say it.', 'source_text' => 'Sebutlah dengan bangga:', 'order' => 671],
            ['start_time' => 2227.92, 'end_time' => 2228.78, 'target_text' => 'Abdul Aziz.', 'source_text' => 'Abdul Aziz!', 'order' => 672],
            ['start_time' => 2228.88, 'end_time' => 2229.42, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 673],
            ['start_time' => 2229.52, 'end_time' => 2230.22, 'target_text' => 'What\'s wrong?', 'source_text' => 'Apa yang salahnya?', 'order' => 674],
            ['start_time' => 2230.32, 'end_time' => 2231.18, 'target_text' => 'May Allah protect you.', 'source_text' => 'Semoga Allah melindungi kamu.', 'order' => 675],
            ['start_time' => 2231.28, 'end_time' => 2232.86, 'target_text' => 'Sorry if anyone\'s name is Abdul Aiz.', 'source_text' => 'Maafkan saya sekiranya ada sesiapa di sini bernama Abdul Aziz.', 'order' => 676],
            ['start_time' => 2232.96, 'end_time' => 2237.499, 'target_text' => 'I don\'t mean you, but I just I\'m just giving an example of a lovely Arabic sounding name.', 'source_text' => 'Saya tidak bermaksud memperkatakan tentang kamu, tetapi saya sekadar memberi contoh nama berbahasa Arab yang begitu indah.', 'order' => 677],
            ['start_time' => 2237.599, 'end_time' => 2238.3, 'target_text' => 'What\'s the problem?', 'source_text' => 'Apakah masalahnya?', 'order' => 678],
            ['start_time' => 2238.4, 'end_time' => 2239.82, 'target_text' => 'Alhamdulillah.', 'source_text' => 'Alhamdulillah.', 'order' => 679],
            ['start_time' => 2239.92, 'end_time' => 2243.9, 'target_text' => 'Muhammad, the best of creation, the most noble of all prophets.', 'source_text' => 'Muhammad, sebaik-baik makhluk ciptaan, nabi yang paling mulia antara sekalian para nabi.', 'order' => 680],
            ['start_time' => 2244.0, 'end_time' => 2247.0, 'target_text' => 'Avoid calling yourself mo.', 'source_text' => 'Elakkan daripada menggelarkan diri kamu sebagai \'Mo\'.', 'order' => 681],
            ['start_time' => 2247.2, 'end_time' => 2250.28, 'target_text' => 'Otherwise, you end up mowing the lawn.', 'source_text' => 'Jika tidak, kamu akan berakhir memotong rumput (mowing the lawn).', 'order' => 682],
            ['start_time' => 2250.96, 'end_time' => 2252.3, 'target_text' => 'May Allah protect us.', 'source_text' => 'Semoga Allah melindungi kita semua.', 'order' => 683],
            ['start_time' => 2252.4, 'end_time' => 2253.739, 'target_text' => 'May Allah protect us.', 'source_text' => 'Semoga Allah melindungi kita semua.', 'order' => 684],
            ['start_time' => 2253.839, 'end_time' => 2259.739, 'target_text' => 'My beloved brothers and sisters, I can go on talking for longer than the whole night.', 'source_text' => 'Wahai saudara-saudari yang saya kasihi, saya boleh terus bercakap lebih lama sepanjang malam.', 'order' => 685],
            ['start_time' => 2259.839, 'end_time' => 2260.78, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 686],
            ['start_time' => 2260.88, 'end_time' => 2262.94, 'target_text' => 'We\'re in Dundee and the night is young.', 'source_text' => 'Kita berada di Dundee dan malam masih muda.', 'order' => 687],
            ['start_time' => 2263.04, 'end_time' => 2264.06, 'target_text' => 'Mashallah.', 'source_text' => 'Masha-Allah.', 'order' => 688],
            ['start_time' => 2264.16, 'end_time' => 2266.3, 'target_text' => 'They say fud is quite early, right?', 'source_text' => 'Mereka kata waktu Subuh agak awal di sini, betul bukan?', 'order' => 689],
            ['start_time' => 2266.4, 'end_time' => 2267.019, 'target_text' => 'Not now.', 'source_text' => 'Bukan sekarang.', 'order' => 690],
            ['start_time' => 2267.119, 'end_time' => 2267.66, 'target_text' => 'Oh, not now.', 'source_text' => 'Oh, bukan sekarang!', 'order' => 691],
            ['start_time' => 2267.76, 'end_time' => 2268.38, 'target_text' => 'Allahbar.', 'source_text' => 'Allahu Akbar.', 'order' => 692],
            ['start_time' => 2268.48, 'end_time' => 2270.46, 'target_text' => 'Okay, he\'s chasing me away.', 'source_text' => 'Baiklah, nampaknya beliau sedang menghalau saya secara halus.', 'order' => 693],
            ['start_time' => 2270.56, 'end_time' => 2272.06, 'target_text' => 'Mashallah', 'source_text' => 'Masha-Allah.', 'order' => 694],
            ['start_time' => 2272.16, 'end_time' => 2272.62, 'target_text' => 'Wah.', 'source_text' => 'Wah.', 'order' => 695],
            ['start_time' => 2272.72, 'end_time' => 2277.499, 'target_text' => 'My brothers and sisters, I I my aim tonight is just to', 'source_text' => 'Saudara dan saudariku sekalian, matlamat saya malam ini hanyalah untuk', 'order' => 696],
            ['start_time' => 2277.599, 'end_time' => 2284.62, 'target_text' => 'Help us to preserve our identity as Muslims and to instill hope among the youth and the youngsters.', 'source_text' => 'Membantu kita semua memelihara identiti kita sebagai Muslim dan menyuntik harapan dalam jiwa para pemuda dan anak-anak belia.', 'order' => 697],
            ['start_time' => 2284.72, 'end_time' => 2286.06, 'target_text' => 'Yes, we know there are challenges.', 'source_text' => 'Ya, kita sedar ada pelbagai cabaran.', 'order' => 698],
            ['start_time' => 2286.16, 'end_time' => 2287.34, 'target_text' => 'There are a lot of challenges.', 'source_text' => 'Terdapat begitu banyak rintangan hidup.', 'order' => 699],
            ['start_time' => 2287.44, 'end_time' => 2288.54, 'target_text' => 'Don\'t be deceived.', 'source_text' => 'Jangan biarkan diri kalian terpedaya.', 'order' => 700],
            ['start_time' => 2288.64, 'end_time' => 2291.739, 'target_text' => 'And especially online, we all have to use technology.', 'source_text' => 'Dan terutamanya di alam maya, kita semua perlu memanfaatkan teknologi.', 'order' => 701],
            ['start_time' => 2291.839, 'end_time' => 2295.019, 'target_text' => 'We all have to use AI, but don\'t be fooled by it.', 'source_text' => 'Kita semua perlu menggunakan kecerdasan buatan (AI), tetapi jangan sesekali diperbodohkan olehnya.', 'order' => 702],
            ['start_time' => 2295.119, 'end_time' => 2297.019, 'target_text' => 'And we all use social media.', 'source_text' => 'Dan kita semua menggunakan media sosial.', 'order' => 703],
            ['start_time' => 2297.119, 'end_time' => 2298.22, 'target_text' => 'Watch out the comment section.', 'source_text' => 'Berhati-hatilah dengan ruangan komen.', 'order' => 704],
            ['start_time' => 2298.32, 'end_time' => 2302.94, 'target_text' => 'And most of those you\'re interacting with are not actually human beings.', 'source_text' => 'Dan sebahagian besar entiti yang berinteraksi dengan kamu bukanlah manusia sebenar.', 'order' => 705],
            ['start_time' => 2303.04, 'end_time' => 2308.62, 'target_text' => 'They are bots and they will highlight things and say nasty things about good people.', 'source_text' => 'Mereka adalah akaun bot dan mereka sengaja menonjolkan tohmahan serta menyebarkan fitnah terhadap orang-orang yang baik.', 'order' => 706],
            ['start_time' => 2308.72, 'end_time' => 2312.7, 'target_text' => 'The hadith of the Prophet ((sallallahu alaihi wasallam)) again we go back to the hadith.', 'source_text' => 'Hadis Nabi (sallallahu \'alaihi wasallam), sekali lagi kita merujuk kepada hadis yang sahih.', 'order' => 707],
            ['start_time' => 2312.8, 'end_time' => 2319.499, 'target_text' => 'He says there will come a time close to the end when the truth will be considered false and the false will be considered true.', 'source_text' => 'Baginda bersabda bahawa akan tiba suatu zaman di ambang kiamat apabila kebenaran dianggap sebagai kepalsuan dan kepalsuan dianggap sebagai kebenaran.', 'order' => 708],
            ['start_time' => 2319.599, 'end_time' => 2321.58, 'target_text' => 'I think we have arrived at that stage.', 'source_text' => 'Saya rasa kita telah pun tiba ke zaman tersebut.', 'order' => 709],
            ['start_time' => 2321.68, 'end_time' => 2323.66, 'target_text' => 'They will show you a proper video.', 'source_text' => 'Mereka akan menunjukkan video yang kelihatan asli.', 'order' => 710],
            ['start_time' => 2323.76, 'end_time' => 2325.739, 'target_text' => 'You will believe someone is a criminal.', 'source_text' => 'Kalian akan mempercayai seseorang itu kononnya seorang penjenayah.', 'order' => 711],
            ['start_time' => 2325.839, 'end_time' => 2329.9, 'target_text' => 'If you are lucky, you might find out that actually this video is fake.', 'source_text' => 'Sekiranya kalian bernasib baik, barulah kalian mengetahui bahawa sebenarnya video itu adalah palsu (deepfake).', 'order' => 712],
            ['start_time' => 2330.0, 'end_time' => 2331.979, 'target_text' => 'It is AI.', 'source_text' => 'Ia adalah rekaan AI.', 'order' => 713],
            ['start_time' => 2332.079, 'end_time' => 2335.019, 'target_text' => 'How many of you have seen AI videos of myself?', 'source_text' => 'Berapa ramai antara kalian yang pernah melihat video AI tentang diri saya?', 'order' => 714],
            ['start_time' => 2335.119, 'end_time' => 2335.519, 'target_text' => 'Me.', 'source_text' => 'Saya.', 'order' => 715],
            ['start_time' => 2335.52, 'end_time' => 2336.38, 'target_text' => 'Me.', 'source_text' => 'Saya.', 'order' => 716],
            ['start_time' => 2336.48, 'end_time' => 2337.58, 'target_text' => 'I\'m watching this video.', 'source_text' => 'Saya sendiri menonton video tersebut.', 'order' => 717],
            ['start_time' => 2337.68, 'end_time' => 2340.46, 'target_text' => 'Someone forwarded me, she was lecture.', 'source_text' => 'Seseorang menghantar kepada saya, kononnya ceramah saya.', 'order' => 718],
            ['start_time' => 2340.56, 'end_time' => 2342.38, 'target_text' => 'I\'m looking at it and I\'m thinking, where was he?', 'source_text' => 'Saya melihatnya dan saya tertanya-tanya: Di manakah ceramah ini disampaikan?', 'order' => 719],
            ['start_time' => 2342.48, 'end_time' => 2343.019, 'target_text' => 'Where was he?', 'source_text' => 'Di manakah lokasi ini?', 'order' => 720],
            ['start_time' => 2343.119, 'end_time' => 2343.82, 'target_text' => 'Where was he?', 'source_text' => 'Di manakah saya bercakap begini?', 'order' => 721],
            ['start_time' => 2343.92, 'end_time' => 2347.34, 'target_text' => 'Few minutes in, I said, AI never ever said this.', 'source_text' => 'Selepas beberapa minit, saya tersedar: Ini AI, saya tidak pernah sama sekali mengucapkan kata-kata ini!', 'order' => 722],
            ['start_time' => 2347.44, 'end_time' => 2349.979, 'target_text' => 'But hey, this is AI.', 'source_text' => 'Tetapi itulah kecanggihan AI.', 'order' => 723],
            ['start_time' => 2350.079, 'end_time' => 2355.499, 'target_text' => 'If it took me so long to figure out that this is not me, imagine you.', 'source_text' => 'Jika saya sendiri mengambil masa sebegitu lama untuk menyedari bahawa itu bukan diri saya, bayangkanlah bagaimana dengan kalian.', 'order' => 724],
            ['start_time' => 2355.599, 'end_time' => 2361.72, 'target_text' => 'Allah Akbar, by the way, the guy sitting in front of you right now is not AI.', 'source_text' => 'Allahu Akbar, apa pun, orang yang sedang duduk di hadapan kalian saat ini bukanlah AI!', 'order' => 725],
            ['start_time' => 2363.2, 'end_time' => 2365.48, 'target_text' => 'Allah Akbar,', 'source_text' => 'Allahu Akbar.', 'order' => 726],
            ['start_time' => 2366.64, 'end_time' => 2367.039, 'target_text' => 'You know.', 'source_text' => 'Kalian faham maksud saya.', 'order' => 727],
            ['start_time' => 2367.04, 'end_time' => 2367.439, 'target_text' => 'Oh, no.', 'source_text' => 'Oh, tidak.', 'order' => 728],
            ['start_time' => 2367.44, 'end_time' => 2369.82, 'target_text' => 'It\'s not a robot either, brother Akbar.', 'source_text' => 'Dia bukan robot juga, wahai saudaraku Akbar.', 'order' => 729],
            ['start_time' => 2369.92, 'end_time' => 2371.18, 'target_text' => 'It\'s not a robot either.', 'source_text' => 'Bukan juga sebuah robot.', 'order' => 730],
            ['start_time' => 2371.28, 'end_time' => 2372.38, 'target_text' => 'Yeah.', 'source_text' => 'Ya.', 'order' => 731],
            ['start_time' => 2372.48, 'end_time' => 2377.18, 'target_text' => 'They say you got to put up your fingers and you put a few fingers down in order to prove that you\'re not AI.', 'source_text' => 'Orang kata kamu perlu angkat jari kamu dan turunkan beberapa jari untuk membuktikan bahawa kamu bukan imej AI.', 'order' => 732],
            ['start_time' => 2377.28, 'end_time' => 2378.22, 'target_text' => 'Have you ever seen that one?', 'source_text' => 'Pernahkah kalian melihat ujian jari itu?', 'order' => 733],
            ['start_time' => 2378.32, 'end_time' => 2379.499, 'target_text' => 'And put it in front of your face.', 'source_text' => 'Dan letakkannya di hadapan muka kamu.', 'order' => 734],
            ['start_time' => 2379.599, 'end_time' => 2381.18, 'target_text' => 'Look guys, there this is me, right?', 'source_text' => 'Lihatlah sahabat-sahabat sekalian, inilah diri saya yang sebenar, bukan?', 'order' => 735],
            ['start_time' => 2381.28, 'end_time' => 2381.739, 'target_text' => 'Four fingers.', 'source_text' => 'Empat jari.', 'order' => 736],
            ['start_time' => 2381.839, 'end_time' => 2382.239, 'target_text' => 'How many?', 'source_text' => 'Berapa banyak?', 'order' => 737],
            ['start_time' => 2382.24, 'end_time' => 2383.1, 'target_text' => 'Four, three.', 'source_text' => 'Empat, tiga.', 'order' => 738],
            ['start_time' => 2383.2, 'end_time' => 2385.1, 'target_text' => 'You see, you still see my face at the back, right?', 'source_text' => 'Kalian nampak, kalian masih boleh melihat wajah saya di belakang jari-jemari ini, bukan?', 'order' => 739],
            ['start_time' => 2385.2, 'end_time' => 2387.019, 'target_text' => 'That\'s me, Allah Akbar.', 'source_text' => 'Inilah diri saya sebenar, Allahu Akbar.', 'order' => 740],
            ['start_time' => 2387.119, 'end_time' => 2388.14, 'target_text' => 'So, I can tell you something.', 'source_text' => 'Maka saya ingin beritahu kalian sesuatu.', 'order' => 741],
            ['start_time' => 2388.24, 'end_time' => 2396.7, 'target_text' => 'When they create an AI video, uh you see how I said uh there\'s no uh it\'s just clear speech going on and on and on, and you', 'source_text' => 'Apabila mereka menjana video AI, kalian perasan bagaimana saya berhenti sejenak menyebut \'uh\', dalam video AI tiada jeda langsung, pertuturannya terlalu lancar berterusan tanpa henti, dan kalian', 'order' => 742],
            ['start_time' => 2396.8, 'end_time' => 2398.3, 'target_text' => 'Think this guy is a machine, man.', 'source_text' => 'Akan menyangka orang ini bercakap seperti sebuah mesin.', 'order' => 743],
            ['start_time' => 2398.4, 'end_time' => 2398.86, 'target_text' => 'Wow.', 'source_text' => 'Hebat sekali.', 'order' => 744],
            ['start_time' => 2398.96, 'end_time' => 2400.62, 'target_text' => 'That\'s AI.', 'source_text' => 'Itulah hasil kerja AI.', 'order' => 745],
            ['start_time' => 2400.72, 'end_time' => 2404.46, 'target_text' => 'Because normal human beings, you pause a little bit, you say uh you breathe, whatever.', 'source_text' => 'Kerana manusia biasa, kita berhenti seketika, kita menyebut \'uh\', kita menarik nafas, dan sebagainya.', 'order' => 746],
            ['start_time' => 2404.56, 'end_time' => 2410.38, 'target_text' => 'But normally what they do is they have this AI this I won\'t tell you which app but anyway there is an app you can say I\'d', 'source_text' => 'Tetapi biasanya apa yang mereka buat ialah mereka mempunyai aplikasi AI ini — saya tidak akan sebut nama aplikasinya — kalian boleh meminta: Saya mahukan', 'order' => 747],
            ['start_time' => 2410.48, 'end_time' => 2419.18, 'target_text' => 'Like a 45minut lecture on the topic of patience in the voice and likeness of Mufti Menk with his style click', 'source_text' => 'Ceramah selama 45 minit mengenai tajuk kesabaran menggunakan suara, wajah dan gaya penyampaian Mufti Menk, hanya dengan satu klik,', 'order' => 748],
            ['start_time' => 2419.28, 'end_time' => 2424.78, 'target_text' => 'A minute or two later it gives you a proper 45minute lecture with a proper background of Mufti Menk talking on the same topic', 'source_text' => 'Satu atau dua minit kemudian ia menghasilkan rakaman ceramah penuh 45 minit berserta latar belakang yang meyakinkan memaparkan Mufti Menk bercakap mengenai topik tersebut,', 'order' => 749],
            ['start_time' => 2424.88, 'end_time' => 2430.22, 'target_text' => 'With the Quran and the Sunnah and all the quotations possibly a little bit of rubbish in the middle but you won\'t notice it', 'source_text' => 'Lengkap dengan petikan ayat Al-Quran dan Sunnah, mungkin diselitkan sedikit kekarutan di celah-celahnya tetapi kalian tidak akan menyedarinya,', 'order' => 750],
            ['start_time' => 2430.32, 'end_time' => 2435.979, 'target_text' => 'But anyway then the person posts it and they say talk on patience And then people are forwarding it.', 'source_text' => 'Kemudian orang itu memuat naiknya di media sosial dengan tajuk: Ceramah Mengenai Kesabaran, lalu orang ramai berkongsi menyebarkannya.', 'order' => 751],
            ['start_time' => 2436.079, 'end_time' => 2442.04, 'target_text' => 'It has 2 million views and people are saying mashallah what a powerful bay', 'source_text' => 'Ia meraih 2 juta tontonan dan orang ramai memuji: Masha-Allah, sungguh hebat pengisian ceramah ini!', 'order' => 752],
            ['start_time' => 2442.8, 'end_time' => 2443.979, 'target_text' => 'May Allah protect us.', 'source_text' => 'Semoga Allah melindungi kita semua.', 'order' => 753],
            ['start_time' => 2444.079, 'end_time' => 2446.54, 'target_text' => 'Wallah we\'re living in an age of deception.', 'source_text' => 'Demi Allah kita sedang hidup dalam zaman penuh tipu daya dan kepalsuan.', 'order' => 754],
            ['start_time' => 2446.64, 'end_time' => 2449.499, 'target_text' => 'Please my beloved youth make use of technology.', 'source_text' => 'Tolonglah wahai anak-anak muda yang saya sayangi, manfaatkan teknologi dengan bijak.', 'order' => 755],
            ['start_time' => 2449.599, 'end_time' => 2456.94, 'target_text' => 'Enjoy the fact that we have infrastructure and development in all ways in this century.', 'source_text' => 'Nikmatilah hakikat bahawa kita mempunyai prasarana dan kemajuan dalam segala aspek pada abad ini.', 'order' => 756],
            ['start_time' => 2457.04, 'end_time' => 2458.46, 'target_text' => 'But don\'t be deceived.', 'source_text' => 'Tetapi jangan sesekali kalian terpedaya.', 'order' => 757],
            ['start_time' => 2458.56, 'end_time' => 2459.18, 'target_text' => 'Be alert.', 'source_text' => 'Sentiasalah peka dan berwaspada.', 'order' => 758],
            ['start_time' => 2459.28, 'end_time' => 2465.739, 'target_text' => 'Be awake and learn to look at what is required of you from Allah and his rasool.', 'source_text' => 'Bangkitlah dan pelajari apa yang dituntut daripada diri kalian oleh Allah dan Rasul-Nya.', 'order' => 759],
            ['start_time' => 2465.839, 'end_time' => 2472.78, 'target_text' => 'May Allah grant us true love of of him and of the messenger (sallallahu alaihi wasallam) and the sahab and may Allah unite us', 'source_text' => 'Semoga Allah mengurniakan kita kecintaan yang tulus kepada-Nya, kepada Rasulullah (sallallahu \'alaihi wasallam) dan kepada para Sahabat, dan semoga Allah menyatukan kita', 'order' => 760],
            ['start_time' => 2472.88, 'end_time' => 2479.979, 'target_text' => 'All and help us to help one another and help us to love one another by his will and his f and his mercy and may Allah put', 'source_text' => 'Semua serta membantu kita saling tolong-menolong dan berkasih sayang atas kehendak-Nya, kurniaan-Nya dan rahmat-Nya, serta semoga Allah menempatkan', 'order' => 761],
            ['start_time' => 2480.079, 'end_time' => 2484.3, 'target_text' => 'Us inshallah in the companionship of Nabi Muhammad (sallallahu alaihi wasallam).', 'source_text' => 'Kita semua insya-Allah bersama Nabi Muhammad (sallallahu \'alaihi wasallam) di akhirat kelak.', 'order' => 762],
            ['start_time' => 2484.4, 'end_time' => 2485.42, 'target_text' => 'I have a lot of hope.', 'source_text' => 'Saya menaruh harapan yang sangat tinggi.', 'order' => 763],
            ['start_time' => 2485.52, 'end_time' => 2489.58, 'target_text' => 'I have a lot of hope and I\'m here to share that hope with you.', 'source_text' => 'Saya mempunyai harapan yang menggunung dan saya hadir di sini untuk berkongsi harapan tersebut bersama kalian.', 'order' => 764],
            ['start_time' => 2489.68, 'end_time' => 2490.38, 'target_text' => 'We try.', 'source_text' => 'Kita berusaha.', 'order' => 765],
            ['start_time' => 2490.48, 'end_time' => 2491.66, 'target_text' => 'Let\'s keep on trying.', 'source_text' => 'Marilah kita terus berusaha gigih.', 'order' => 766],
            ['start_time' => 2491.76, 'end_time' => 2493.66, 'target_text' => 'We know all of us have committed sins.', 'source_text' => 'Kita sedar bahawa kita semua pernah melakukan dosa.', 'order' => 767],
            ['start_time' => 2493.76, 'end_time' => 2500.86, 'target_text' => 'We all have a past perhaps we all might be even in at the moment we might have a few things we\'re not doing so right.', 'source_text' => 'Kita semua mempunyai masa silam, bahkan saat ini mungkin ada beberapa perkara yang kita lakukan secara kurang tepat.', 'order' => 768],
            ['start_time' => 2500.96, 'end_time' => 2501.9, 'target_text' => 'Make an intention.', 'source_text' => 'Pasanglah niat yang suci.', 'order' => 769],
            ['start_time' => 2502.0, 'end_time' => 2502.7, 'target_text' => 'Be strong.', 'source_text' => 'Kuatkanlah azam.', 'order' => 770],
            ['start_time' => 2502.8, 'end_time' => 2505.019, 'target_text' => 'Be firm and improve every day.', 'source_text' => 'Kekal teguh dan perbaikilah diri setiap hari.', 'order' => 771],
            ['start_time' => 2505.119, 'end_time' => 2506.78, 'target_text' => 'Keep seeking the forgiveness of Allah.', 'source_text' => 'Sentiasalah memohon keampunan daripada Allah (istighfar).', 'order' => 772],
            ['start_time' => 2506.88, 'end_time' => 2508.3, 'target_text' => 'And keep pushing yourself.', 'source_text' => 'Dan teruslah mendesak diri kalian ke arah kebaikan.', 'order' => 773],
            ['start_time' => 2508.4, 'end_time' => 2510.94, 'target_text' => 'If you don\'t push yourself, nobody\'s going to push yourself.', 'source_text' => 'Jika kalian tidak memaksa diri kalian sendiri, tiada siapa yang akan memaksa kalian.', 'order' => 774],
            ['start_time' => 2511.04, 'end_time' => 2512.3, 'target_text' => 'You\'re doing SOMETHING BAD.', 'source_text' => 'Sekiranya kamu sedang melakukan perbuatan yang buruk,', 'order' => 775],
            ['start_time' => 2512.4, 'end_time' => 2513.66, 'target_text' => 'PUSH YOURSELF TO QUIT IT.', 'source_text' => 'Paksa dirimu untuk berhenti meninggalkannya!', 'order' => 776],
            ['start_time' => 2513.76, 'end_time' => 2514.94, 'target_text' => 'Keep on making dua.', 'source_text' => 'Teruskanlah memanjatkan doa.', 'order' => 777],
            ['start_time' => 2515.04, 'end_time' => 2517.019, 'target_text' => 'Oh Allah, strengthen me to quit my sins.', 'source_text' => 'Wahai Allah, kurniakanlah daku kekuatan untuk meninggalkan dosa-dosaku.', 'order' => 778],
            ['start_time' => 2517.119, 'end_time' => 2518.62, 'target_text' => 'Strengthen me to quit my sins.', 'source_text' => 'Kurniakanlah daku kekuatan untuk meninggalkan dosa-dosaku.', 'order' => 779],
            ['start_time' => 2518.72, 'end_time' => 2520.3, 'target_text' => 'Make me strong so I quit my sins.', 'source_text' => 'Jadikanlah daku kuat agar daku mampu meninggalkan dosa-dosaku.', 'order' => 780],
            ['start_time' => 2520.4, 'end_time' => 2521.58, 'target_text' => 'Keep repeating that dua.', 'source_text' => 'Ulang-ulanglah doa tersebut.', 'order' => 781],
